-- Additive zero-price semantics; preserve every historical row and migration.
-- DDL statements commit separately. Stop and inspect on failure; never retry/reset blindly.
-- ENUM value is appended, preserving existing ordinals. No payment facts are backfilled.
ALTER TABLE `Order`
    MODIFY `paymentStatus` ENUM('UNPAID','PENDING_VERIFICATION','PAID','REFUND_PENDING','REFUNDED','NOT_REQUIRED') NOT NULL DEFAULT 'UNPAID',
    ADD CONSTRAINT `Order_no_payment_required_check` CHECK (
      `paymentStatus` <> 'NOT_REQUIRED' OR
      (`amountFen` = 0 AND `paidAt` IS NULL AND `paymentConfirmedAt` IS NULL
       AND `fulfillmentStatus` IN ('PROCESSING','COMPLETED','CANCELLED'))
    );

-- Extend the existing strict V1 whitelist only by its new legal payment enum value.
-- Replacing the CHECK in one ALTER leaves no externally visible unprotected interval.
