      JSON_SCHEMA_VALID('{"type":"object","required":["snapshotSchemaVersion","order"],"additionalProperties":false,"properties":{"snapshotSchemaVersion":{"type":"integer","enum":[1]},"order":{"type":"object","required":["id","orderNo","userId","productId","productNameSnapshot","termSnapshot","contactEmailSnapshot","subscriptionId","productDescriptionSnapshot","targetIdentifier","cancellationReason","internalNote","createdByAdminId","createdByUserId","billingTimezoneSnapshot","amountFen","version","priceSnapshotFen","servicePeriodCountSnapshot","renewalPriceSnapshotFen","billingRevisionSnapshot","createdAt","updatedAt","paidAt","paymentRecordedAt","paymentConfirmedAt","fulfilledAt","cancelledAt","renewalPeriodStartAt","renewalPeriodEndAt","renewalForPeriodStartAt","billingAnchorSnapshotAt","kind","source","productTypeSnapshot","paymentStatus","fulfillmentStatus","servicePeriodUnitSnapshot","hidden","formSchemaSnapshot","formData"],"additionalProperties":false,"properties":{"id":{"type":"string"},"orderNo":{"type":"string"},"userId":{"type":"string"},"productId":{"type":"string"},"productNameSnapshot":{"type":"string"},"termSnapshot":{"type":"string"},"contactEmailSnapshot":{"type":"string"},"subscriptionId":{"type":["string","null"]},"productDescriptionSnapshot":{"type":["string","null"]},"targetIdentifier":{"type":["string","null"]},"cancellationReason":{"type":["string","null"]},"internalNote":{"type":["string","null"]},"createdByAdminId":{"type":["string","null"]},"createdByUserId":{"type":["string","null"]},"billingTimezoneSnapshot":{"type":["string","null"]},"amountFen":{"type":"integer","minimum":0},"version":{"type":"integer","minimum":1},"priceSnapshotFen":{"type":["integer","null"]},"servicePeriodCountSnapshot":{"type":["integer","null"]},"renewalPriceSnapshotFen":{"type":["integer","null"]},"billingRevisionSnapshot":{"type":["integer","null"]},"createdAt":{"type":"string"},"updatedAt":{"type":"string"},"paidAt":{"type":["string","null"]},"paymentRecordedAt":{"type":["string","null"]},"paymentConfirmedAt":{"type":["string","null"]},"fulfilledAt":{"type":["string","null"]},"cancelledAt":{"type":["string","null"]},"renewalPeriodStartAt":{"type":["string","null"]},"renewalPeriodEndAt":{"type":["string","null"]},"renewalForPeriodStartAt":{"type":["string","null"]},"billingAnchorSnapshotAt":{"type":["string","null"]},"kind":{"type":"string","enum":["INITIAL","RENEWAL","ONE_TIME"]},"source":{"type":"string","enum":["USER","ADMIN","SYSTEM_RENEWAL"]},"productTypeSnapshot":{"type":"string","enum":["SUBSCRIPTION","ONE_TIME"]},"paymentStatus":{"type":"string","enum":["UNPAID","PENDING_VERIFICATION","PAID","REFUND_PENDING","REFUNDED","NOT_REQUIRED"]},"fulfillmentStatus":{"type":"string","enum":["NOT_STARTED","PROCESSING","COMPLETED","FAILED","CANCELLED"]},"servicePeriodUnitSnapshot":{"type":["string","null"],"enum":["DAY","MONTH","YEAR",null]},"hidden":{"type":"boolean"},"formSchemaSnapshot":{},"formData":{}}}}}', `snapshotJson`)
      AND CAST(JSON_UNQUOTE(JSON_EXTRACT(`snapshotJson`, '$.order.id')) AS BINARY) = CAST(`orderId` AS BINARY)
      AND JSON_EXTRACT(`snapshotJson`, '$.order.version') = `version`
      AND JSON_EXTRACT(`snapshotJson`, '$.snapshotSchemaVersion') = `snapshotSchemaVersion`
    );
